def chains(cells,D):
    """cells sorted by dot along D; group into contiguous runs"""
    if not cells: return []
    s=sorted(cells,key=lambda p:(p[0]*D[0]+p[1]*D[1]))
    runs=[s[:1]]
    for p in s[1:]:
        last=runs[-1][-1]
        if p==(tuple(last)+D) if isinstance(tuple(last),tuple) else p==(last+D):
            runs[-1].append(p)
        else:
            runs.append([p])
    return runs
